import React from 'react';
import { Trophy, Medal, Award } from 'lucide-react';

function Leaderboard() {
  const topUsers = [
    { id: 1, name: 'Rajesh Kumar', points: 1250, reports: 45, rank: 1 },
    { id: 2, name: 'Priya Sharma', points: 980, reports: 38, rank: 2 },
    { id: 3, name: 'Amit Patel', points: 875, reports: 32, rank: 3 },
    { id: 4, name: 'Sneha Reddy', points: 720, reports: 28, rank: 4 },
    { id: 5, name: 'Vikram Singh', points: 650, reports: 25, rank: 5 },
    { id: 6, name: 'Anita Desai', points: 580, reports: 22, rank: 6 },
    { id: 7, name: 'Rahul Verma', points: 520, reports: 19, rank: 7 },
    { id: 8, name: 'Kavita Joshi', points: 480, reports: 17, rank: 8 },
  ];

  const getRankIcon = (rank) => {
    if (rank === 1) return <Trophy size={24} color="#FFD700" />;
    if (rank === 2) return <Medal size={24} color="#C0C0C0" />;
    if (rank === 3) return <Award size={24} color="#CD7F32" />;
    return <span style={{ fontSize: '18px', fontWeight: '700' }}>#{rank}</span>;
  };

  const getRankColor = (rank) => {
    if (rank === 1) return '#FFD700';
    if (rank === 2) return '#C0C0C0';
    if (rank === 3) return '#CD7F32';
    return '#000080';
  };

  return (
    <div style={{ maxWidth: '900px', margin: '0 auto', padding: '20px' }}>
      <h1 style={{ 
        fontSize: '28px', 
        fontWeight: '700', 
        color: '#000080',
        marginBottom: '10px'
      }}>
        Community Leaderboard
      </h1>
      <p style={{ color: '#666', marginBottom: '30px' }}>
        Top contributors making a difference in their communities
      </p>

      <div style={{
        backgroundColor: 'white',
        borderRadius: '16px',
        boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
        overflow: 'hidden'
      }}>
        {topUsers.map((user, index) => (
          <div
            key={user.id}
            style={{
              display: 'flex',
              alignItems: 'center',
              padding: '20px',
              borderBottom: index < topUsers.length - 1 ? '1px solid #F0F0F0' : 'none',
              backgroundColor: user.rank <= 3 ? '#FFF9F0' : 'white',
              transition: 'background-color 0.2s'
            }}
          >
            <div style={{
              width: '50px',
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              color: getRankColor(user.rank)
            }}>
              {getRankIcon(user.rank)}
            </div>

            <div style={{ flex: 1, marginLeft: '15px' }}>
              <h3 style={{
                fontSize: '18px',
                fontWeight: '600',
                color: '#000080',
                marginBottom: '5px'
              }}>
                {user.name}
              </h3>
              <p style={{ fontSize: '14px', color: '#666' }}>
                {user.reports} reports submitted
              </p>
            </div>

            <div style={{
              textAlign: 'right'
            }}>
              <div style={{
                fontSize: '24px',
                fontWeight: '700',
                color: '#FF9933'
              }}>
                {user.points}
              </div>
              <div style={{
                fontSize: '12px',
                color: '#666',
                textTransform: 'uppercase'
              }}>
                Points
              </div>
            </div>
          </div>
        ))}
      </div>

      <div style={{
        marginTop: '30px',
        padding: '20px',
        backgroundColor: '#E8F5E9',
        borderRadius: '12px',
        border: '2px solid #138808'
      }}>
        <h3 style={{
          fontSize: '18px',
          fontWeight: '600',
          color: '#138808',
          marginBottom: '10px'
        }}>
          How to Earn Points
        </h3>
        <ul style={{ color: '#2E7D32', lineHeight: '1.8' }}>
          <li>Report an issue: <strong>+20 points</strong></li>
          <li>Issue gets resolved: <strong>+50 points</strong></li>
          <li>Upvote from community: <strong>+5 points</strong></li>
          <li>Helpful comment: <strong>+10 points</strong></li>
        </ul>
      </div>
    </div>
  );
}

export default Leaderboard;
